176.     public async Task<bool> PullAndRestoreAsync(
177.         RepoEntry repo,
178.         string l5xGitExePath,
179.         Action<string> onOutput,
180.         CancellationToken cancellationToken = default)
181.     {
182.         AppLogger.Info($"PullAndRestoreAsync starting for repo '{repo.Name}', git repo: {repo.GitRepoPath}");
183. 
184.         if (!ValidatePathsForRestore(repo, l5xGitExePath, onOutput))
185.         {
186.             AppLogger.Warn($"PullAndRestoreAsync aborted — path validation failed for repo '{repo.Name}'.");
187.             return false;
188.         }
189. 
190.         onOutput("[git pull] Pulling latest from remote...");
191.         int gitExitCode = await RunProcessAsync(
192.             exePath: "git",
193.             arguments: ["-C", repo.GitRepoPath, "pull"],
194.             stdinInput: null,
195.             onOutput: onOutput,
196.             cancellationToken: cancellationToken);
197. 
198.         if (gitExitCode != 0)
199.         {
200.             var msg = $"git pull failed (exit code {gitExitCode}). Restore cancelled to prevent overwriting with stale content.";
201.             onOutput($"[abort] {msg}");
202.             AppLogger.Error($"PullAndRestoreAsync — {msg} — repo '{repo.Name}'.");
203.             return false;
204.         }
205. 
206.         if (cancellationToken.IsCancellationRequested)
207.         {
208.             AppLogger.Info($"PullAndRestoreAsync cancelled after git pull for repo '{repo.Name}'.");
209.             return false;
210.         }
211. 
212.         var restored = await RestoreAcdOnlyAsync(repo, l5xGitExePath, onOutput, cancellationToken);
213. 
214.         AppLogger.Info($"PullAndRestoreAsync finished for repo '{repo.Name}' — restore succeeded: {restored}.");
215.         return restored;
216.     }
217. 
218.     /// <summary>
219.     /// Runs just the ACD-rebuild half of the restore workflow:
220.     ///   l5xgit restoreacd --acd &lt;acdPath&gt;
221.     /// Pipes "y" to stdin to confirm overwriting the existing ACD file. Does not run
222.     /// <c>git pull</c> — callers that already updated the working tree (via a git pull or a
223.     /// specific-commit restore) use this to rebuild the ACD from the current file state.
224.     /// </summary>
225.     /// <param name="repo">Repository entry containing ACD and git paths.</param>
226.     /// <param name="l5xGitExePath">Full path to l5xgit.exe.</param>
227.     /// <param name="onOutput">Callback invoked for each line of stdout/stderr.</param>
228.     /// <param name="cancellationToken">Token to cancel the operation mid-flight.</param>
229.     public async Task<bool> RestoreAcdOnlyAsync(
230.         RepoEntry repo,
231.         string l5xGitExePath,
232.         Action<string> onOutput,
233.         CancellationToken cancellationToken = default)
234.     {
235.         AppLogger.Info($"RestoreAcdOnlyAsync starting for repo '{repo.Name}', git repo: {repo.GitRepoPath}");
236. 
237.         if (!ValidatePathsForRestore(repo, l5xGitExePath, onOutput))
238.         {
239.             AppLogger.Warn($"RestoreAcdOnlyAsync aborted — path validation failed for repo '{repo.Name}'.");
240.             return false;
241.         }
242. 
243.         EnsureL5xGitYml(repo.AcdFilePath, repo.GitRepoPath);
244. 
245.         onOutput("[restoreacd] Imploding and converting to ACD...");
246.         int restoreExitCode = await RunProcessAsync(
247.             exePath: l5xGitExePath,
248.             arguments: ["restoreacd", "--acd", repo.AcdFilePath],
249.             stdinInput: "y\n",
250.             onOutput: onOutput,
251.             cancellationToken: cancellationToken);
252. 
253.         AppLogger.Info($"RestoreAcdOnlyAsync finished for repo '{repo.Name}' — restoreacd exit code {restoreExitCode}.");
254.         return restoreExitCode == 0;
255.     }
256. 
