260. 
261.     /// <summary>
262.     /// Validates l5xgit.exe, the ACD file, and the git repo before a commit.
263.     /// Writes a user-readable error to <paramref name="onOutput"/> on failure.
264.     /// </summary>
265.     private static L5xGitOperationResult ValidatePaths(
266.         RepoEntry repo,
267.         string l5xGitExePath,
268.         Action<string> onOutput)
269.     {
270.         if (string.IsNullOrWhiteSpace(l5xGitExePath))
271.         {
272.             onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
273.             AppLogger.Warn("ValidatePaths failed — l5xgit.exe path is empty.");
274.             return L5xGitOperationResult.Failed;
275.         }
276. 
277.         if (!File.Exists(l5xGitExePath))
278.         {
279.             onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
280.             AppLogger.Warn($"ValidatePaths failed — l5xgit.exe not found: {l5xGitExePath}");
281.             return L5xGitOperationResult.Failed;
282.         }
283. 
284.         if (!File.Exists(repo.AcdFilePath))
285.         {
286.             onOutput($"[error] ACD file not found: {repo.AcdFilePath}");
287.             AppLogger.Warn($"ValidatePaths failed — ACD not found: {repo.AcdFilePath}");
288.             return L5xGitOperationResult.Failed;
289.         }
290. 
291.         if (!Directory.Exists(repo.GitRepoPath))
292.         {
293.             onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
294.             AppLogger.Warn($"ValidatePaths failed — git repo not found: {repo.GitRepoPath}");
295.             return L5xGitOperationResult.Failed;
296.         }
297. 
298.         if (!IsGitWorkingTree(repo.GitRepoPath))
299.         {
300.             AppLogger.Warn($"ValidatePaths failed — directory exists but is not a git working tree: {repo.GitRepoPath}");
301.             return L5xGitOperationResult.GitRepositoryRequired;
302.         }
303. 
304.         return L5xGitOperationResult.Succeeded;
305.     }
306. 
307.     /// <summary>
308.     /// Validates l5xgit.exe and the git repo before a restore.
309.     /// The ACD file is not required to exist before restore (it will be created by l5xgit).
310.     /// </summary>
311.     private static bool ValidatePathsForRestore(RepoEntry repo, string l5xGitExePath, Action<string> onOutput)
312.     {
313.         if (string.IsNullOrWhiteSpace(l5xGitExePath))
314.         {
315.             onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
316.             AppLogger.Warn("ValidatePathsForRestore failed — l5xgit.exe path is empty.");
317.             return false;
318.         }
319. 
320.         if (!File.Exists(l5xGitExePath))
321.         {
322.             onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
323.             AppLogger.Warn($"ValidatePathsForRestore failed — l5xgit.exe not found: {l5xGitExePath}");
324.             return false;
325.         }
326. 
327.         if (!Directory.Exists(repo.GitRepoPath))
328.         {
329.             onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
330.             AppLogger.Warn($"ValidatePathsForRestore failed — git repo not found: {repo.GitRepoPath}");
331.             return false;
332.         }
333. 
334.         if (!IsGitWorkingTree(repo.GitRepoPath))
335.         {
336.             onOutput($"[error] No Git repository found at '{repo.GitRepoPath}'. Initialize a repo (git init), clone one, or select the correct repository folder.");
337.             AppLogger.Warn($"ValidatePathsForRestore failed — directory exists but is not a git working tree: {repo.GitRepoPath}");
338.             return false;
339.         }
340. 
341.         return true;
342.     }
343. 
344.     /// <summary>
345.     /// Determines whether a directory is a git working tree.
346.     /// </summary>
347.     public static bool IsGitWorkingTree(string repoPath)
348.     {
349.         if (!Directory.Exists(repoPath))
350.             return false;
351. 
352.         var dotGitPath = Path.Combine(repoPath, ".git");
353.         if (Directory.Exists(dotGitPath) || File.Exists(dotGitPath))
354.             return true;
355. 
356.         try
357.         {
358.             var psi = new ProcessStartInfo("git")
359.             {
360.                 UseShellExecute = false,
361.                 CreateNoWindow = true,
362.                 RedirectStandardOutput = true,
363.                 RedirectStandardError = true,
364.             };
365.             psi.ArgumentList.Add("-C");
366.             psi.ArgumentList.Add(repoPath);
367.             psi.ArgumentList.Add("rev-parse");
368.             psi.ArgumentList.Add("--show-toplevel");
369. 
370.             using var process = Process.Start(psi);
371.             if (process is null)
372.                 return false;
373. 
374.             var output = process.StandardOutput.ReadToEnd();
375.             process.WaitForExit();
376. 
377.             if (process.ExitCode != 0 || string.IsNullOrWhiteSpace(output))
378.                 return false;
379. 
380.             var selectedPath = Path.GetFullPath(repoPath)
381.                 .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
382.             var repositoryRoot = Path.GetFullPath(output.Trim())
