     private static L5xGitOperationResult ValidatePaths(
         RepoEntry repo,
         string l5xGitExePath,
         Action<string> onOutput)
     {
         if (string.IsNullOrWhiteSpace(l5xGitExePath))
         {
             onOutput("[error] l5xgit.exe path is not configured. Open Settings to configure it.");
             AppLogger.Warn("ValidatePaths failed — l5xgit.exe path is empty.");
             return L5xGitOperationResult.Failed;
         }

         if (!File.Exists(l5xGitExePath))
         {
             onOutput($"[error] l5xgit.exe not found at: {l5xGitExePath}");
             AppLogger.Warn($"ValidatePaths failed — l5xgit.exe not found: {l5xGitExePath}");
             return L5xGitOperationResult.Failed;
         }

         if (!File.Exists(repo.AcdFilePath))
         {
             onOutput($"[error] ACD file not found: {repo.AcdFilePath}");
             AppLogger.Warn($"ValidatePaths failed — ACD not found: {repo.AcdFilePath}");
             return L5xGitOperationResult.Failed;
         }

         if (!Directory.Exists(repo.GitRepoPath))
         {
             onOutput($"[error] Git repository path not found: {repo.GitRepoPath}");
             AppLogger.Warn($"ValidatePaths failed — git repo not found: {repo.GitRepoPath}");
             return L5xGitOperationResult.Failed;
         }

         if (!IsGitWorkingTree(repo.GitRepoPath))
         {
             AppLogger.Warn($"ValidatePaths failed — directory exists but is not a git working tree: {repo.GitRepoPath}");
             return L5xGitOperationResult.GitRepositoryRequired;
         }

         return L5xGitOperationResult.Succeeded;
     }

