     /// <summary>
     /// Determines whether a directory is a git working tree.
     /// </summary>
     public static bool IsGitWorkingTree(string repoPath)
     {
         if (!Directory.Exists(repoPath))
             return false;

         var dotGitPath = Path.Combine(repoPath, ".git");
         if (Directory.Exists(dotGitPath) || File.Exists(dotGitPath))
             return true;

         try
         {
             var psi = new ProcessStartInfo("git")
             {
                 UseShellExecute = false,
                 CreateNoWindow = true,
                 RedirectStandardOutput = true,
                 RedirectStandardError = true,
             };
             psi.ArgumentList.Add("-C");
             psi.ArgumentList.Add(repoPath);
             psi.ArgumentList.Add("rev-parse");
             psi.ArgumentList.Add("--show-toplevel");

             using var process = Process.Start(psi);
             if (process is null)
                 return false;

             var output = process.StandardOutput.ReadToEnd();
             process.WaitForExit();

             if (process.ExitCode != 0 || string.IsNullOrWhiteSpace(output))
                 return false;

             var selectedPath = Path.GetFullPath(repoPath)
                 .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
             var repositoryRoot = Path.GetFullPath(output.Trim())
                 .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);

             return string.Equals(selectedPath, repositoryRoot, StringComparison.OrdinalIgnoreCase);
         }
         catch (Exception ex)
         {
             AppLogger.Error($"IsGitWorkingTree probe failed for '{repoPath}'.", ex);
             return false;
         }
     }

