357.     // -------------------------------------------------------------------------
358.     // Process helpers
359.     // -------------------------------------------------------------------------
360. 
361.     /// <summary>
362.     /// Runs <c>git</c> with the given arguments, capturing all stdout lines for parsing.
363.     /// Used for read-only queries (log, branch listing, status).
364.     /// </summary>
365.     private static async Task<(int ExitCode, List<string> Lines)> RunCapturingAsync(
366.         IEnumerable<string> arguments,
367.         CancellationToken cancellationToken)
368.     {
369.         var argList = arguments.ToList();
370.         AppLogger.Info($"Launching: git {string.Join(" ", argList.Select(a => $"\"{a}\""))}");
371. 
372.         var psi = new ProcessStartInfo("git")
373.         {
374.             RedirectStandardOutput = true,
375.             RedirectStandardError = true,
376.             UseShellExecute = false,
377.             CreateNoWindow = true,
378.         };
379.         foreach (var arg in argList)
380.             psi.ArgumentList.Add(arg);
381. 
382.         var lines = new List<string>();
383. 
384.         try
385.         {
386.             using var process = new Process { StartInfo = psi };
387.             process.Start();
388. 
389.             var stdoutTask = process.StandardOutput.ReadToEndAsync(cancellationToken);
390.             var stderrTask = process.StandardError.ReadToEndAsync(cancellationToken);
391.             await process.WaitForExitAsync(cancellationToken);
392. 
393.             var stdout = await stdoutTask;
394.             var stderr = await stderrTask;
395. 
396.             if (!string.IsNullOrWhiteSpace(stderr))
397.                 AppLogger.Warn($"git stderr: {stderr.Trim()}");
398. 
399.             lines.AddRange(stdout.Split('\n').Select(l => l.TrimEnd('\r')));
400. 
401.             return (process.ExitCode, lines);
402.         }
403.         catch (Exception ex)
404.         {
405.             AppLogger.Error("RunCapturingAsync failed to launch or read git output.", ex);
406.             return (-1, lines);
407.         }
408.     }
409. 
410.     /// <summary>
411.     /// Runs <c>git</c> with the given arguments, streaming stdout/stderr lines to
412.     /// <paramref name="onOutput"/> as they arrive. Used for user-facing, potentially
413.     /// long-running or state-changing operations.
414.     /// </summary>
415.     private static async Task<int> RunStreamingAsync(
416.         IEnumerable<string> arguments,
417.         string? stdinInput,
418.         Action<string> onOutput,
419.         CancellationToken cancellationToken)
420.     {
421.         var argList = arguments.ToList();
422.         AppLogger.Info($"Launching: git {string.Join(" ", argList.Select(a => $"\"{a}\""))}");
423. 
424.         var psi = new ProcessStartInfo("git")
425.         {
426.             RedirectStandardInput = true,
427.             RedirectStandardOutput = true,
428.             RedirectStandardError = true,
429.             UseShellExecute = false,
430.             CreateNoWindow = true,
431.         };
432.         foreach (var arg in argList)
433.             psi.ArgumentList.Add(arg);
434. 
435.         using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };
436. 
437.         process.OutputDataReceived += (_, e) => { if (e.Data is not null) onOutput(e.Data); };
438.         process.ErrorDataReceived += (_, e) => { if (e.Data is not null) onOutput($"[stderr] {e.Data}"); };
439. 
440.         try
441.         {
442.             process.Start();
443.             process.BeginOutputReadLine();
444.             process.BeginErrorReadLine();
445. 
446.             if (stdinInput is not null)
