 using System.Diagnostics;
 using System.IO;
 using System.Text.RegularExpressions;
 using ABLogixGitManager.Models;

 namespace ABLogixGitManager.Services;

 /// <summary>
 /// Shells out to <c>git</c> for read/write repository metadata operations: commit history,
 /// branch listing, branch create/checkout/delete, and restoring working-tree files from a
 /// specific historical commit. Complements <see cref="L5xGitCliService"/>, which owns the
 /// <c>l5xgit</c>-orchestrated commit/restore workflow.
 /// </summary>
 /// <remarks>
 /// Every public method logs its start, validation failures, and outcome to <see cref="AppLogger"/>.
 /// All destructive operations (checkout, branch delete, commit-file restore) require the caller
 /// to have already confirmed with the user; this service does not prompt.
 /// </remarks>
 public class GitRepositoryService
 {
     // Field separator unlikely to appear in commit metadata; matches git's %x1f (unit separator).
     private const string FieldSeparator = "\u001f";

     // -------------------------------------------------------------------------
     // History
     // -------------------------------------------------------------------------

     /// <summary>
     /// Loads up to <paramref name="maxCount"/> commits across all branches, parsed from
     /// <c>git log --all --graph</c>, including the leading ASCII-art graph prefix git renders
     /// for each line.
     /// </summary>
     public async Task<List<GitCommitInfo>> GetCommitGraphAsync(
         string repoPath,
         int maxCount = 300,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"GetCommitGraphAsync starting for '{repoPath}' (max {maxCount}).");

         var commits = new List<GitCommitInfo>();

         if (!Directory.Exists(repoPath))
         {
             AppLogger.Warn($"GetCommitGraphAsync aborted — repo path not found: {repoPath}");
             return commits;
         }

         var format = string.Join(FieldSeparator, "%H", "%h", "%an", "%ad", "%s", "%D");

         var (exitCode, lines) = await RunCapturingAsync(
             [
                 "-C", repoPath,
                 "log", "--all", "--graph",
                 "--date=iso-strict",
                 $"--pretty=format:{format}",
                 $"--max-count={maxCount}",
             ],
             cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"GetCommitGraphAsync — git log exited with code {exitCode} for '{repoPath}'.");
             return commits;
         }

         // A commit's SHA is always exactly 40 hex characters; everything preceding it on the
         // first physical line of the formatted output is the ASCII graph prefix git inserted.
         var shaPattern = new Regex("^(?<prefix>[^0-9a-fA-F]*)(?<sha>[0-9a-fA-F]{40})$");

         foreach (var line in lines)
         {
             if (string.IsNullOrWhiteSpace(line))
                 continue;

             var fields = line.Split(FieldSeparator);
             if (fields.Length < 6)
                 continue; // Graph-only continuation line (no commit on it) — skip.

             var match = shaPattern.Match(fields[0]);
             if (!match.Success)
                 continue;

             commits.Add(new GitCommitInfo
             {
                 GraphPrefix = match.Groups["prefix"].Value,
                 Sha = match.Groups["sha"].Value,
                 ShortSha = fields[1],
                 Author = fields[2],
                 Date = fields[3],
                 Subject = fields[4],
                 RefNames = fields[5],
             });
         }

         AppLogger.Info($"GetCommitGraphAsync completed for '{repoPath}' — {commits.Count} commit(s) parsed.");
         return commits;
     }

     // -------------------------------------------------------------------------
     // Branches
     // -------------------------------------------------------------------------

     /// <summary>Lists local branches and remote-tracking branches, flagging the current branch.</summary>
     public async Task<List<GitBranchInfo>> GetBranchesAsync(
         string repoPath,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"GetBranchesAsync starting for '{repoPath}'.");

         var branches = new List<GitBranchInfo>();

         if (!Directory.Exists(repoPath))
         {
             AppLogger.Warn($"GetBranchesAsync aborted — repo path not found: {repoPath}");
             return branches;
         }

         var (localExitCode, localLines) = await RunCapturingAsync(
             ["-C", repoPath, "branch", "--list"], cancellationToken);

         if (localExitCode != 0)
         {
             AppLogger.Warn($"GetBranchesAsync — git branch --list exited with code {localExitCode} for '{repoPath}'.");
         }
         else
         {
             foreach (var line in localLines)
             {
                 if (string.IsNullOrWhiteSpace(line)) continue;
                 var isCurrent = line.StartsWith('*');
                 var name = line.TrimStart('*', '+', ' ').Trim();
                 if (name.Length == 0 || name.Contains("detached at") || name.Contains("detached from"))
                     continue;

                 branches.Add(new GitBranchInfo { Name = name, IsCurrent = isCurrent, IsRemote = false });
             }
         }

         var (remoteExitCode, remoteLines) = await RunCapturingAsync(
             ["-C", repoPath, "branch", "-r"], cancellationToken);

         if (remoteExitCode != 0)
         {
             AppLogger.Warn($"GetBranchesAsync — git branch -r exited with code {remoteExitCode} for '{repoPath}'.");
         }
         else
         {
             foreach (var line in remoteLines)
             {
                 var name = line.Trim();
                 if (name.Length == 0 || name.Contains("->"))
                     continue; // Skip the "origin/HEAD -> origin/main" alias line.

                 branches.Add(new GitBranchInfo { Name = name, IsCurrent = false, IsRemote = true });
             }
         }

         AppLogger.Info($"GetBranchesAsync completed for '{repoPath}' — {branches.Count} branch(es) found.");
         return branches;
     }

     /// <summary>
     /// Creates a new local branch. Fails with a user-visible message if the name is blank or
     /// already exists.
     /// </summary>
     public async Task<bool> CreateBranchAsync(
         string repoPath,
         string branchName,
         string? startPoint,
         Action<string> onOutput,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"CreateBranchAsync starting for '{branchName}' in '{repoPath}'.");

         if (string.IsNullOrWhiteSpace(branchName))
         {
             onOutput("[error] Branch name is required.");
             AppLogger.Warn("CreateBranchAsync failed — missing branch name.");
             return false;
         }

         var args = new List<string> { "-C", repoPath, "branch", branchName };
         if (!string.IsNullOrWhiteSpace(startPoint))
             args.Add(startPoint);

         var exitCode = await RunStreamingAsync(args, stdinInput: null, onOutput, cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"CreateBranchAsync failed — git branch exit code {exitCode} for '{branchName}'.");
             return false;
         }

         onOutput($"[done] Created branch: {branchName}");
         AppLogger.Info($"CreateBranchAsync completed for '{branchName}' in '{repoPath}'.");
         return true;
     }

     /// <summary>
     /// Checks out a branch. Blocks (returns <c>false</c> with a message) if the working tree has
     /// uncommitted changes, rather than silently discarding or stashing them. When
     /// <paramref name="isRemote"/> is <c>true</c>, <paramref name="branchName"/> must be a
     /// remote-tracking name (e.g. <c>origin/xyz</c>); a local tracking branch is created
     /// (<c>git checkout --track -b xyz origin/xyz</c>) unless a local branch with that short
     /// name already exists, in which case that local branch is checked out directly.
     /// </summary>
     public async Task<bool> CheckoutBranchAsync(
         string repoPath,
         string branchName,
         bool isRemote,
         Action<string> onOutput,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"CheckoutBranchAsync starting for '{branchName}' (remote: {isRemote}) in '{repoPath}'.");

         if (await HasUncommittedChangesAsync(repoPath, cancellationToken))
         {
             onOutput("[error] Working tree has uncommitted changes. Commit or discard them before switching branches.");
             AppLogger.Warn($"CheckoutBranchAsync blocked — uncommitted changes present in '{repoPath}'.");
             return false;
         }

         List<string> args;

         if (!isRemote)
         {
             args = ["-C", repoPath, "checkout", branchName];
         }
         else
         {
             var localName = branchName.Contains('/') ? branchName[(branchName.IndexOf('/') + 1)..] : branchName;
             var existingLocalBranches = await GetBranchesAsync(repoPath, cancellationToken);
             var localAlreadyExists = existingLocalBranches.Any(b => !b.IsRemote &&
                 string.Equals(b.Name, localName, StringComparison.Ordinal));

             args = localAlreadyExists
                 ? ["-C", repoPath, "checkout", localName]
                 : ["-C", repoPath, "checkout", "--track", "-b", localName, branchName];
         }

         var exitCode = await RunStreamingAsync(args, stdinInput: null, onOutput, cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"CheckoutBranchAsync failed — git checkout exit code {exitCode} for '{branchName}'.");
             return false;
         }

         onOutput($"[done] Checked out: {branchName}");
         AppLogger.Info($"CheckoutBranchAsync completed for '{branchName}' in '{repoPath}'.");
         return true;
     }

     /// <summary>
     /// Deletes a local branch. Refuses to delete the current branch. Attempts a safe delete
     /// (<c>git branch -d</c>) first; the caller must explicitly re-invoke with
     /// <paramref name="force"/> <c>true</c> after confirming with the user when the safe delete
     /// fails because the branch is not fully merged.
     /// </summary>
     public async Task<bool> DeleteBranchAsync(
         string repoPath,
         string branchName,
         bool force,
         Action<string> onOutput,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"DeleteBranchAsync starting for '{branchName}' (force: {force}) in '{repoPath}'.");

         var branches = await GetBranchesAsync(repoPath, cancellationToken);
         var target = branches.FirstOrDefault(b => !b.IsRemote &&
             string.Equals(b.Name, branchName, StringComparison.Ordinal));

         if (target is null)
         {
             onOutput($"[error] Local branch not found: {branchName}");
             AppLogger.Warn($"DeleteBranchAsync failed — branch not found: {branchName}");
             return false;
         }

         if (target.IsCurrent)
         {
             onOutput("[error] Cannot delete the currently checked-out branch. Switch to a different branch first.");
             AppLogger.Warn($"DeleteBranchAsync blocked — attempted to delete current branch '{branchName}'.");
             return false;
         }

         var deleteFlag = force ? "-D" : "-d";
         var exitCode = await RunStreamingAsync(
             ["-C", repoPath, "branch", deleteFlag, branchName], stdinInput: null, onOutput, cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"DeleteBranchAsync failed — git branch {deleteFlag} exit code {exitCode} for '{branchName}'.");
             return false;
         }

         onOutput($"[done] Deleted branch: {branchName}");
         AppLogger.Info($"DeleteBranchAsync completed for '{branchName}' in '{repoPath}'.");
         return true;
     }

     // -------------------------------------------------------------------------
     // Working-tree state
     // -------------------------------------------------------------------------

     /// <summary>True when <c>git status --porcelain</c> reports any pending changes.</summary>
     public async Task<bool> HasUncommittedChangesAsync(string repoPath, CancellationToken cancellationToken = default)
     {
         var (exitCode, lines) = await RunCapturingAsync(
             ["-C", repoPath, "status", "--porcelain"], cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"HasUncommittedChangesAsync — git status exited with code {exitCode} for '{repoPath}'.");
             return false;
         }

         return lines.Any(l => !string.IsNullOrWhiteSpace(l));
     }

     /// <summary>
     /// Restores tracked working-tree files to their state at <paramref name="commitSha"/> via
     /// <c>git checkout &lt;sha&gt; -- .</c>. This does <b>not</b> move <c>HEAD</c> or change the
     /// current branch — it only overwrites working-tree file contents, leaving the result as an
     /// uncommitted change the user can re-commit or discard. Callers must confirm with the user
     /// (and check <see cref="HasUncommittedChangesAsync"/>) before invoking this.
     /// </summary>
     public async Task<bool> RestoreCommitFilesAsync(
         string repoPath,
         string commitSha,
         Action<string> onOutput,
         CancellationToken cancellationToken = default)
     {
         AppLogger.Info($"RestoreCommitFilesAsync starting for commit '{commitSha}' in '{repoPath}'.");

         if (string.IsNullOrWhiteSpace(commitSha))
         {
             onOutput("[error] No commit selected.");
             AppLogger.Warn("RestoreCommitFilesAsync failed — missing commit sha.");
             return false;
         }

         var exitCode = await RunStreamingAsync(
             ["-C", repoPath, "checkout", commitSha, "--", "."], stdinInput: null, onOutput, cancellationToken);

         if (exitCode != 0)
         {
             AppLogger.Warn($"RestoreCommitFilesAsync failed — git checkout exit code {exitCode} for commit '{commitSha}'.");
             return false;
         }

         onOutput($"[done] Working tree restored to commit {commitSha}.");
         AppLogger.Info($"RestoreCommitFilesAsync completed for commit '{commitSha}' in '{repoPath}'.");
         return true;
     }

     // -------------------------------------------------------------------------
     // Process helpers
     // -------------------------------------------------------------------------

     /// <summary>
     /// Runs <c>git</c> with the given arguments, capturing all stdout lines for parsing.
     /// Used for read-only queries (log, branch listing, status).
     /// </summary>
     private static async Task<(int ExitCode, List<string> Lines)> RunCapturingAsync(
         IEnumerable<string> arguments,
         CancellationToken cancellationToken)
     {
         var argList = arguments.ToList();
         AppLogger.Info($"Launching: git {string.Join(" ", argList.Select(a => $"\"{a}\""))}");

         var psi = new ProcessStartInfo("git")
         {
             RedirectStandardOutput = true,
             RedirectStandardError = true,
             UseShellExecute = false,
             CreateNoWindow = true,
         };
         foreach (var arg in argList)
             psi.ArgumentList.Add(arg);

         var lines = new List<string>();

         try
         {
             using var process = new Process { StartInfo = psi };
             process.Start();

             var stdoutTask = process.StandardOutput.ReadToEndAsync(cancellationToken);
             var stderrTask = process.StandardError.ReadToEndAsync(cancellationToken);
             await process.WaitForExitAsync(cancellationToken);

             var stdout = await stdoutTask;
             var stderr = await stderrTask;

             if (!string.IsNullOrWhiteSpace(stderr))
                 AppLogger.Warn($"git stderr: {stderr.Trim()}");

             lines.AddRange(stdout.Split('\n').Select(l => l.TrimEnd('\r')));

             return (process.ExitCode, lines);
         }
         catch (Exception ex)
         {
             AppLogger.Error("RunCapturingAsync failed to launch or read git output.", ex);
             return (-1, lines);
         }
     }

     /// <summary>
     /// Runs <c>git</c> with the given arguments, streaming stdout/stderr lines to
     /// <paramref name="onOutput"/> as they arrive. Used for user-facing, potentially
     /// long-running or state-changing operations.
     /// </summary>
     private static async Task<int> RunStreamingAsync(
         IEnumerable<string> arguments,
         string? stdinInput,
         Action<string> onOutput,
         CancellationToken cancellationToken)
     {
         var argList = arguments.ToList();
         AppLogger.Info($"Launching: git {string.Join(" ", argList.Select(a => $"\"{a}\""))}");

         var psi = new ProcessStartInfo("git")
         {
             RedirectStandardInput = true,
             RedirectStandardOutput = true,
             RedirectStandardError = true,
             UseShellExecute = false,
             CreateNoWindow = true,
         };
         foreach (var arg in argList)
             psi.ArgumentList.Add(arg);

         using var process = new Process { StartInfo = psi, EnableRaisingEvents = true };

         process.OutputDataReceived += (_, e) => { if (e.Data is not null) onOutput(e.Data); };
         process.ErrorDataReceived += (_, e) => { if (e.Data is not null) onOutput($"[stderr] {e.Data}"); };

         try
         {
             process.Start();
             process.BeginOutputReadLine();
             process.BeginErrorReadLine();

             if (stdinInput is not null)
                 await process.StandardInput.WriteAsync(stdinInput);

             process.StandardInput.Close();

             await process.WaitForExitAsync(cancellationToken);

             if (process.ExitCode != 0)
             {
                 onOutput($"[exit code {process.ExitCode}] git finished with errors.");
                 AppLogger.Warn($"git process exited with code {process.ExitCode}.");
             }
             else
             {
                 AppLogger.Info("git process completed successfully.");
             }

             return process.ExitCode;
         }
         catch (Exception ex)
         {
             onOutput($"[error] Failed to run git: {ex.Message}");
             AppLogger.Error("RunStreamingAsync failed to launch git.", ex);
             return -1;
         }
     }
 }

