50.         options.AddRange(branches.Select(b => new StartPointOption
51.         {
52.             Display = b.IsCurrent ? $"{b.Name} (current)" : b.Name,
53.             Value = b.Name,
54.         }));
55.         options.AddRange(commits.Select(c => new StartPointOption
56.         {
57.             Display = $"{c.ShortSha} — {c.Subject}",
58.             Value = c.Sha,
59.         }));
