 using System.Collections.Generic;
 using System.Linq;
 using System.Windows;
 using ABLogixGitManager.Models;

 namespace ABLogixGitManager.Views;

 /// <summary>
 /// Small dialog that prompts for a new local branch name and a start point selected from the
 /// repository's known branches and commits (a read-only drop-down, not freeform text, so a typo
 /// can't produce an invalid or unintended git ref).
 /// </summary>
 public partial class NewBranchWindow : Window
 {
     /// <summary>
     /// One selectable entry in the Start Point drop-down: a human-readable label plus the exact
     /// git ref (branch name or full commit SHA) to pass to <c>git branch</c>. <see cref="Value"/>
     /// is <c>null</c> for the "current HEAD" option, so the caller omits the start-point argument.
     /// </summary>
     private sealed class StartPointOption
     {
         public string Display { get; init; } = string.Empty;
         public string? Value { get; init; }
     }

     /// <summary>The trimmed branch name entered by the user, or empty if none was entered.</summary>
     public string BranchName => BranchNameBox.Text.Trim();

     /// <summary>
     /// The git ref (branch name or commit SHA) selected in the Start Point drop-down, or
     /// <c>null</c> when "Current HEAD" is selected so the caller can omit it and let git default
     /// to <c>HEAD</c>.
     /// </summary>
     public string? StartPoint => StartPointBox.SelectedValue as string;

     /// <param name="branches">Known local/remote branches, offered as start-point choices.</param>
     /// <param name="commits">Known commits, offered as start-point choices (newest first).</param>
     /// <param name="defaultStartPoint">
     /// Pre-selects this branch/commit in the start-point drop-down, e.g. the currently selected
     /// branch. Falls back to "Current HEAD" if it does not match any offered option.
     /// </param>
     public NewBranchWindow(
         IEnumerable<GitBranchInfo> branches,
         IEnumerable<GitCommitInfo> commits,
         string? defaultStartPoint = null)
     {
         InitializeComponent();

         var options = new List<StartPointOption> { new() { Display = "Current HEAD", Value = null } };
         options.AddRange(branches.Select(b => new StartPointOption
         {
             Display = b.IsCurrent ? $"{b.Name} (current)" : b.Name,
             Value = b.Name,
         }));
         options.AddRange(commits.Select(c => new StartPointOption
         {
             Display = $"{c.ShortSha} — {c.Subject}",
             Value = c.Sha,
         }));

         StartPointBox.ItemsSource = options;
         StartPointBox.SelectedIndex = 0;

         if (!string.IsNullOrWhiteSpace(defaultStartPoint))
         {
             var match = options.FirstOrDefault(o => o.Value == defaultStartPoint);
             if (match is not null)
                 StartPointBox.SelectedItem = match;
         }

         Loaded += (_, _) =>
         {
             Activate();
             Topmost = true;
             Topmost = false;
             BranchNameBox.Focus();
         };
     }

     private void Create_Click(object sender, RoutedEventArgs e)
     {
         if (string.IsNullOrWhiteSpace(BranchName))
         {
             MessageBox.Show("Please enter a branch name.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
             BranchNameBox.Focus();
             return;
         }

         DialogResult = true;
     }

     private void Cancel_Click(object sender, RoutedEventArgs e) => DialogResult = false;
 }

