166.     /// <summary>Checks out the selected branch (local or a new local tracking branch for a remote).</summary>
167.     [RelayCommand(CanExecute = nameof(CanCheckoutBranch))]
168.     private async Task CheckoutBranchAsync()
169.     {
170.         if (SelectedBranch is null) return;
171. 
172.         var confirm = MessageBox.Show(
173.             ActiveWindow,
174.             $"Switch the working tree to \"{SelectedBranch.Name}\"?",
175.             "Checkout Branch",
176.             MessageBoxButton.YesNo,
177.             MessageBoxImage.Question);
178. 
179.         if (confirm != MessageBoxResult.Yes) return;
180. 
181.         IsBusy = true;
182.         StatusMessage = $"Checking out '{SelectedBranch.Name}'...";
183.         AppLogger.Info($"GitHistoryViewModel.CheckoutBranchAsync starting — branch '{SelectedBranch.Name}' in repo '{_repo.Name}'.");
184. 
185.         try
186.         {
187.             var ct = BeginOperation();
188.             var ok = await _gitService.CheckoutBranchAsync(
189.                 _repo.GitRepoPath, SelectedBranch.Name, SelectedBranch.IsRemote, AppendLog, ct);
190. 
191.             StatusMessage = ok ? $"Checked out '{SelectedBranch.Name}'." : "Checkout failed. See log.";
192.             AppLogger.Info($"GitHistoryViewModel.CheckoutBranchAsync completed for '{SelectedBranch.Name}' — success: {ok}.");
193.         }
194.         catch (Exception ex)
195.         {
196.             StatusMessage = $"Checkout failed: {ex.Message}";
197.             AppendLog($"[error] Checkout failed: {ex.Message}");
