208.     /// <summary>
209.     /// Deletes the selected local branch. Tries a safe delete first; if git reports the branch
210.     /// is not fully merged, asks the user to explicitly confirm a force delete before retrying.
211.     /// </summary>
212.     [RelayCommand(CanExecute = nameof(CanDeleteBranch))]
213.     private async Task DeleteBranchAsync()
214.     {
215.         if (SelectedBranch is null) return;
216. 
217.         var branchName = SelectedBranch.Name;
218.         var confirm = MessageBox.Show(
219.             ActiveWindow,
220.             $"Delete local branch \"{branchName}\"?\n\nThis cannot be undone from this application.",
221.             "Delete Branch",
222.             MessageBoxButton.YesNo,
223.             MessageBoxImage.Warning);
224. 
225.         if (confirm != MessageBoxResult.Yes) return;
226. 
227.         IsBusy = true;
228.         StatusMessage = $"Deleting branch '{branchName}'...";
229.         AppLogger.Info($"GitHistoryViewModel.DeleteBranchAsync starting — branch '{branchName}' in repo '{_repo.Name}'.");
230. 
231.         try
232.         {
233.             var ct = BeginOperation();
234.             var ok = await _gitService.DeleteBranchAsync(_repo.GitRepoPath, branchName, force: false, AppendLog, ct);
235. 
236.             if (!ok)
237.             {
238.                 var forceConfirm = MessageBox.Show(
239.                     ActiveWindow,
240.                     $"\"{branchName}\" is not fully merged and could not be safely deleted.\n\n" +
241.                     "Force-deleting can permanently lose commits that exist only on this branch. Force delete anyway?",
242.                     "Force Delete Branch",
243.                     MessageBoxButton.YesNo,
244.                     MessageBoxImage.Warning);
245. 
246.                 if (forceConfirm == MessageBoxResult.Yes)
247.                 {
248.                     AppLogger.Warn($"GitHistoryViewModel.DeleteBranchAsync — user confirmed force delete for '{branchName}'.");
249.                     ok = await _gitService.DeleteBranchAsync(_repo.GitRepoPath, branchName, force: true, AppendLog, ct);
250.                 }
251.             }
252. 
253.             StatusMessage = ok ? $"Deleted branch '{branchName}'." : "Branch deletion failed. See log.";
254.             AppLogger.Info($"GitHistoryViewModel.DeleteBranchAsync completed for '{branchName}' — success: {ok}.");
255.         }
256.         catch (Exception ex)
257.         {
258.             StatusMessage = $"Branch deletion failed: {ex.Message}";
259.             AppendLog($"[error] Branch deletion failed: {ex.Message}");
260.             AppLogger.Error("GitHistoryViewModel.DeleteBranchAsync failed.", ex);
261.         }
262.         finally
263.         {
264.             EndOperation();
265.         }
266. 
267.         await RefreshAsync();
268.     }
269. 
270.     /// <summary>
271.     /// Restores working-tree files from the selected commit (without moving HEAD/branches) and
272.     /// re-runs <c>l5xgit restoreacd</c> to rebuild the ACD from those files. Requires explicit
273.     /// confirmation, and a second confirmation if uncommitted changes would be overwritten.
274.     /// </summary>
275.     [RelayCommand(CanExecute = nameof(CanRestoreCommit))]
276.     private async Task RestoreCommitAsync()
277.     {
278.         if (SelectedCommit is null) return;
279. 
280.         var shortSha = SelectedCommit.ShortSha;
281. 
282.         var confirm = MessageBox.Show(
283.             ActiveWindow,
284.             $"Restore the ACD to commit {shortSha} — \"{SelectedCommit.Subject}\"?\n\n" +
285.             "This overwrites the current working files and the ACD. The result is left as an " +
286.             "uncommitted change you can re-commit or discard; it does not move the current branch.",
287.             "Restore Commit",
288.             MessageBoxButton.YesNo,
289.             MessageBoxImage.Warning);
290. 
291.         if (confirm != MessageBoxResult.Yes) return;
292. 
293.         IsBusy = true;
294.         StatusMessage = $"Restoring commit {shortSha}...";
295.         AppLogger.Info($"GitHistoryViewModel.RestoreCommitAsync starting — commit '{SelectedCommit.Sha}' in repo '{_repo.Name}'.");
296. 
297.         try
298.         {
299.             var ct = BeginOperation();
300. 
301.             if (await _gitService.HasUncommittedChangesAsync(_repo.GitRepoPath, ct))
302.             {
303.                 var discardConfirm = MessageBox.Show(
304.                     ActiveWindow,
305.                     "The working tree has uncommitted changes. Restoring this commit will overwrite " +
306.                     "those files. Continue and discard the uncommitted changes?",
307.                     "Uncommitted Changes",
308.                     MessageBoxButton.YesNo,
309.                     MessageBoxImage.Warning);
310. 
311.                 if (discardConfirm != MessageBoxResult.Yes)
312.                 {
313.                     StatusMessage = "Restore cancelled — uncommitted changes were kept.";
314.                     AppLogger.Info($"GitHistoryViewModel.RestoreCommitAsync cancelled by user due to uncommitted changes in repo '{_repo.Name}'.");
315.                     return;
316.                 }
317.             }
318. 
319.             var filesRestored = await _gitService.RestoreCommitFilesAsync(_repo.GitRepoPath, SelectedCommit.Sha, AppendLog, ct);
320.             if (!filesRestored)
321.             {
322.                 StatusMessage = "Restore failed while checking out commit files. See log.";
323.                 AppLogger.Warn($"GitHistoryViewModel.RestoreCommitAsync aborted — RestoreCommitFilesAsync failed for commit '{SelectedCommit.Sha}'.");
324.                 return;
325.             }
326. 
327.             var acdRestored = await _cliService.RestoreAcdOnlyAsync(_repo, _l5xGitExePath, AppendLog, ct);
328.             StatusMessage = acdRestored
329.                 ? $"ACD restored to commit {shortSha}."
330.                 : "Commit files were restored, but rebuilding the ACD failed. See log.";
331. 
332.             AppLogger.Info($"GitHistoryViewModel.RestoreCommitAsync completed for commit '{SelectedCommit.Sha}' — ACD restored: {acdRestored}.");
333.         }
334.         catch (Exception ex)
335.         {
336.             StatusMessage = $"Restore failed: {ex.Message}";
337.             AppendLog($"[error] Restore failed: {ex.Message}");
338.             AppLogger.Error("GitHistoryViewModel.RestoreCommitAsync failed.", ex);
339.         }
340.         finally
341.         {
342.             EndOperation();
343.         }
344.     }
345. 
346.     /// <summary>Cancels the in-progress operation, if any.</summary>
347.     [RelayCommand(CanExecute = nameof(IsBusy))]
348.     private void CancelOperation()
349.     {
350.         _cts?.Cancel();
351.         AppLogger.Info($"GitHistoryViewModel — cancellation requested for repo '{_repo.Name}'.");
352.     }
353. 
354.     private bool CanRunOperation() => !IsBusy;
355. 
356.     private bool CanCheckoutBranch() => !IsBusy && SelectedBranch is not null && !SelectedBranch.IsCurrent;
357. 
358.     private bool CanDeleteBranch() => !IsBusy && SelectedBranch is not null && !SelectedBranch.IsCurrent && !SelectedBranch.IsRemote;
359. 
360.     private bool CanRestoreCommit() => !IsBusy && SelectedCommit is not null;
361. 
362.     private CancellationToken BeginOperation()
363.     {
364.         _cts = new CancellationTokenSource();
365.         return _cts.Token;
366.     }
367. 
368.     private void EndOperation()
369.     {
370.         IsBusy = false;
371.         _cts?.Dispose();
372.         _cts = null;
373.     }
374. 
375.     private void AppendLog(string message)
376.     {
377.         var ts = DateTime.Now.ToString("HH:mm:ss");
378.         LogOutput += $"[{ts}] {message}{Environment.NewLine}";
379.     }
380. }
