                 Commits.Add(commit);

             Branches.Clear();
             foreach (var branch in branches)
                 Branches.Add(branch);

             StatusMessage = $"{Commits.Count} commit(s), {Branches.Count} branch(es).";
             AppLogger.Info($"GitHistoryViewModel.RefreshAsync completed for repo '{_repo.Name}' — {Commits.Count} commit(s), {Branches.Count} branch(es).");
         }
         catch (Exception ex)
         {
             StatusMessage = $"Failed to load history: {ex.Message}";
             AppendLog($"[error] Failed to load history: {ex.Message}");
             AppLogger.Error($"GitHistoryViewModel.RefreshAsync failed for repo '{_repo.Name}'.", ex);
         }
         finally
         {
             EndOperation();
         }
     }

     /// <summary>Opens a small dialog to name a new local branch, then creates it.</summary>
     [RelayCommand(CanExecute = nameof(CanRunOperation))]
     private async Task CreateBranchAsync()
     {
         var dialog = new NewBranchWindow(Branches, Commits, SelectedBranch?.Name) { Owner = ActiveWindow };
         if (dialog.ShowDialog() != true || string.IsNullOrWhiteSpace(dialog.BranchName))
             return;

         IsBusy = true;
         StatusMessage = $"Creating branch '{dialog.BranchName}'...";
         AppLogger.Info($"GitHistoryViewModel.CreateBranchAsync starting — branch '{dialog.BranchName}' in repo '{_repo.Name}'.");

         try
         {
             var ct = BeginOperation();
             var ok = await _gitService.CreateBranchAsync(
                 _repo.GitRepoPath, dialog.BranchName, dialog.StartPoint, AppendLog, ct);

             StatusMessage = ok ? $"Created branch '{dialog.BranchName}'." : "Branch creation failed. See log.";
             AppLogger.Info($"GitHistoryViewModel.CreateBranchAsync completed for '{dialog.BranchName}' — success: {ok}.");
         }
         catch (Exception ex)
         {
             StatusMessage = $"Branch creation failed: {ex.Message}";
             AppendLog($"[error] Branch creation failed: {ex.Message}");
             AppLogger.Error("GitHistoryViewModel.CreateBranchAsync failed.", ex);
         }
         finally
         {
             EndOperation();
         }

         await RefreshAsync();
     }

     /// <summary>Checks out the selected branch (local or a new local tracking branch for a remote).</summary>
     [RelayCommand(CanExecute = nameof(CanCheckoutBranch))]
     private async Task CheckoutBranchAsync()
     {
         if (SelectedBranch is null) return;

         var confirm = MessageBox.Show(
             ActiveWindow,
             $"Switch the working tree to \"{SelectedBranch.Name}\"?",
             "Checkout Branch",
             MessageBoxButton.YesNo,
             MessageBoxImage.Question);

         if (confirm != MessageBoxResult.Yes) return;

         IsBusy = true;
         StatusMessage = $"Checking out '{SelectedBranch.Name}'...";
         AppLogger.Info($"GitHistoryViewModel.CheckoutBranchAsync starting — branch '{SelectedBranch.Name}' in repo '{_repo.Name}'.");

         try
         {
             var ct = BeginOperation();
             var ok = await _gitService.CheckoutBranchAsync(
                 _repo.GitRepoPath, SelectedBranch.Name, SelectedBranch.IsRemote, AppendLog, ct);

             StatusMessage = ok ? $"Checked out '{SelectedBranch.Name}'." : "Checkout failed. See log.";
             AppLogger.Info($"GitHistoryViewModel.CheckoutBranchAsync completed for '{SelectedBranch.Name}' — success: {ok}.");
         }
         catch (Exception ex)
         {
             StatusMessage = $"Checkout failed: {ex.Message}";
             AppendLog($"[error] Checkout failed: {ex.Message}");
             AppLogger.Error("GitHistoryViewModel.CheckoutBranchAsync failed.", ex);
         }
         finally
         {
             EndOperation();
         }

         await RefreshAsync();
     }

     /// <summary>
     /// Deletes the selected local branch. Tries a safe delete first; if git reports the branch
     /// is not fully merged, asks the user to explicitly confirm a force delete before retrying.
     /// </summary>
     [RelayCommand(CanExecute = nameof(CanDeleteBranch))]
     private async Task DeleteBranchAsync()
     {
         if (SelectedBranch is null) return;

         var branchName = SelectedBranch.Name;
         var confirm = MessageBox.Show(
             ActiveWindow,
             $"Delete local branch \"{branchName}\"?\n\nThis cannot be undone from this application.",
             "Delete Branch",
             MessageBoxButton.YesNo,
             MessageBoxImage.Warning);

         if (confirm != MessageBoxResult.Yes) return;

         IsBusy = true;
         StatusMessage = $"Deleting branch '{branchName}'...";
         AppLogger.Info($"GitHistoryViewModel.DeleteBranchAsync starting — branch '{branchName}' in repo '{_repo.Name}'.");

         try
         {
             var ct = BeginOperation();
             var ok = await _gitService.DeleteBranchAsync(_repo.GitRepoPath, branchName, force: false, AppendLog, ct);

             if (!ok)
             {
                 var forceConfirm = MessageBox.Show(
                     ActiveWindow,
                     $"\"{branchName}\" is not fully merged and could not be safely deleted.\n\n" +
                     "Force-deleting can permanently lose commits that exist only on this branch. Force delete anyway?",
                     "Force Delete Branch",
                     MessageBoxButton.YesNo,
                     MessageBoxImage.Warning);

                 if (forceConfirm == MessageBoxResult.Yes)
                 {
                     AppLogger.Warn($"GitHistoryViewModel.DeleteBranchAsync — user confirmed force delete for '{branchName}'.");
                     ok = await _gitService.DeleteBranchAsync(_repo.GitRepoPath, branchName, force: true, AppendLog, ct);
                 }
             }

             StatusMessage = ok ? $"Deleted branch '{branchName}'." : "Branch deletion failed. See log.";
             AppLogger.Info($"GitHistoryViewModel.DeleteBranchAsync completed for '{branchName}' — success: {ok}.");
         }
         catch (Exception ex)
         {
             StatusMessage = $"Branch deletion failed: {ex.Message}";
             AppendLog($"[error] Branch deletion failed: {ex.Message}");
             AppLogger.Error("GitHistoryViewModel.DeleteBranchAsync failed.", ex);
         }
         finally
         {
             EndOperation();
         }

         await RefreshAsync();
     }

     /// <summary>
     /// Restores working-tree files from the selected commit (without moving HEAD/branches) and
     /// re-runs <c>l5xgit restoreacd</c> to rebuild the ACD from those files. Requires explicit
     /// confirmation, and a second confirmation if uncommitted changes would be overwritten.
     /// </summary>
     [RelayCommand(CanExecute = nameof(CanRestoreCommit))]
     private async Task RestoreCommitAsync()
     {
         if (SelectedCommit is null) return;

         var shortSha = SelectedCommit.ShortSha;

         var confirm = MessageBox.Show(
             ActiveWindow,
             $"Restore the ACD to commit {shortSha} — \"{SelectedCommit.Subject}\"?\n\n" +
             "This overwrites the current working files and the ACD. The result is left as an " +
             "uncommitted change you can re-commit or discard; it does not move the current branch.",
             "Restore Commit",
             MessageBoxButton.YesNo,
             MessageBoxImage.Warning);

         if (confirm != MessageBoxResult.Yes) return;

         IsBusy = true;
         StatusMessage = $"Restoring commit {shortSha}...";
         AppLogger.Info($"GitHistoryViewModel.RestoreCommitAsync starting — commit '{SelectedCommit.Sha}' in repo '{_repo.Name}'.");

         try
         {
             var ct = BeginOperation();

             if (await _gitService.HasUncommittedChangesAsync(_repo.GitRepoPath, ct))
             {
                 var discardConfirm = MessageBox.Show(
                     ActiveWindow,
                     "The working tree has uncommitted changes. Restoring this commit will overwrite " +
                     "those files. Continue and discard the uncommitted changes?",
                     "Uncommitted Changes",
                     MessageBoxButton.YesNo,
                     MessageBoxImage.Warning);

                 if (discardConfirm != MessageBoxResult.Yes)
                 {
                     StatusMessage = "Restore cancelled — uncommitted changes were kept.";
                     AppLogger.Info($"GitHistoryViewModel.RestoreCommitAsync cancelled by user due to uncommitted changes in repo '{_repo.Name}'.");
                     return;
                 }
             }

             var filesRestored = await _gitService.RestoreCommitFilesAsync(_repo.GitRepoPath, SelectedCommit.Sha, AppendLog, ct);
             if (!filesRestored)
             {
                 StatusMessage = "Restore failed while checking out commit files. See log.";
                 AppLogger.Warn($"GitHistoryViewModel.RestoreCommitAsync aborted — RestoreCommitFilesAsync failed for commit '{SelectedCommit.Sha}'.");
                 return;
             }

             var acdRestored = await _cliService.RestoreAcdOnlyAsync(_repo, _l5xGitExePath, AppendLog, ct);
             StatusMessage = acdRestored
                 ? $"ACD restored to commit {shortSha}."
                 : "Commit files were restored, but rebuilding the ACD failed. See log.";

             AppLogger.Info($"GitHistoryViewModel.RestoreCommitAsync completed for commit '{SelectedCommit.Sha}' — ACD restored: {acdRestored}.");
         }
         catch (Exception ex)
         {
             StatusMessage = $"Restore failed: {ex.Message}";
             AppendLog($"[error] Restore failed: {ex.Message}");
             AppLogger.Error("GitHistoryViewModel.RestoreCommitAsync failed.", ex);
         }
         finally
         {
             EndOperation();
         }
     }

     /// <summary>Cancels the in-progress operation, if any.</summary>
     [RelayCommand(CanExecute = nameof(IsBusy))]
     private void CancelOperation()
     {
         _cts?.Cancel();
         AppLogger.Info($"GitHistoryViewModel — cancellation requested for repo '{_repo.Name}'.");
     }

     private bool CanRunOperation() => !IsBusy;

     private bool CanCheckoutBranch() => !IsBusy && SelectedBranch is not null && !SelectedBranch.IsCurrent;

     private bool CanDeleteBranch() => !IsBusy && SelectedBranch is not null && !SelectedBranch.IsCurrent && !SelectedBranch.IsRemote;

     private bool CanRestoreCommit() => !IsBusy && SelectedCommit is not null;

     private CancellationToken BeginOperation()
     {
         _cts = new CancellationTokenSource();
         return _cts.Token;
     }

     private void EndOperation()
     {
         IsBusy = false;
         _cts?.Dispose();
         _cts = null;
     }

     private void AppendLog(string message)
     {
         var ts = DateTime.Now.ToString("HH:mm:ss");
         LogOutput += $"[{ts}] {message}{Environment.NewLine}";
     }
 }

