/// <summary>Lists configured remote names (e.g. <c>origin</c>), or an empty list if none exist.</summary>
public async Task<List<string>> GetRemotesAsync(string repoPath, CancellationToken cancellationToken = default)
{
    var (exitCode, lines) = await RunCapturingAsync(["-C", repoPath, "remote"], cancellationToken);
    if (exitCode != 0)
    {
        AppLogger.Warn($"GetRemotesAsync — git remote exited with code {exitCode} for '{repoPath}'.");
        return [];
    }

    return lines.Where(l => !string.IsNullOrWhiteSpace(l)).Select(l => l.Trim()).ToList();
}

/// <summary>Returns the short name of the currently checked-out branch, or <c>null</c> when detached/unknown.</summary>
public async Task<string?> GetCurrentBranchNameAsync(string repoPath, CancellationToken cancellationToken = default)
{
    var (exitCode, lines) = await RunCapturingAsync(
        ["-C", repoPath, "rev-parse", "--abbrev-ref", "HEAD"], cancellationToken);

    if (exitCode != 0)
    {
        AppLogger.Warn($"GetCurrentBranchNameAsync — git rev-parse exited with code {exitCode} for '{repoPath}'.");
        return null;
    }

    var name = lines.FirstOrDefault(l => !string.IsNullOrWhiteSpace(l))?.Trim();
    return string.IsNullOrWhiteSpace(name) || name == "HEAD" ? null : name;
}

