    public async Task<bool> PullAndRestoreAsync(
        RepoEntry repo,
        string l5xGitExePath,
        Action<string> onOutput,
        CancellationToken cancellationToken = default,
        string? branchName = null)
    {
        AppLogger.Info(
            $"PullAndRestoreAsync starting for repo '{repo.Name}', git repo: {repo.GitRepoPath}, " +
            $"branch: {branchName ?? "(current)"}");

        if (!ValidatePathsForRestore(repo, l5xGitExePath, onOutput))
        {
            AppLogger.Warn($"PullAndRestoreAsync aborted — path validation failed for repo '{repo.Name}'.");
            return false;
        }

        if (!string.IsNullOrWhiteSpace(branchName) &&
            !await SwitchToBranchAsync(repo.GitRepoPath, branchName, onOutput, cancellationToken))
        {
            return false;
        }

        var remotes = await _gitService.GetRemotesAsync(repo.GitRepoPath, cancellationToken);
        if (remotes.Count == 0)
        {
            onOutput("[git pull] No remote configured for this repository — restoring from the local working tree only.");
            AppLogger.Info($"PullAndRestoreAsync — no remote configured for '{repo.Name}'; skipping git pull.");
        }
        else
        {
            onOutput("[git pull] Pulling latest from remote...");
            int gitExitCode = await RunProcessAsync(
                exePath: "git",
                arguments: ["-C", repo.GitRepoPath, "pull"],
                stdinInput: null,
                onOutput: onOutput,
                cancellationToken: cancellationToken);

            if (gitExitCode != 0)
                gitExitCode = await RetryPullWithExplicitBranchAsync(repo.GitRepoPath, remotes, onOutput, cancellationToken);

            if (gitExitCode != 0)
            {
                var msg = $"git pull failed (exit code {gitExitCode}). Restore cancelled to prevent overwriting with stale content.";
                onOutput($"[abort] {msg}");
                AppLogger.Error($"PullAndRestoreAsync — {msg} — repo '{repo.Name}'.");
                return false;
            }
        }

        if (cancellationToken.IsCancellationRequested)
        {
            AppLogger.Info($"PullAndRestoreAsync cancelled after git pull for repo '{repo.Name}'.");
            return false;
        }

        var restored = await RestoreAcdOnlyAsync(repo, l5xGitExePath, onOutput, cancellationToken);

        AppLogger.Info($"PullAndRestoreAsync finished for repo '{repo.Name}' — restore succeeded: {restored}.");
        return restored;
    }

    /// <summary>
    /// Retries a failed bare <c>git pull</c> by resolving the current branch name and reissuing
    /// it as <c>git pull &lt;remote&gt; &lt;branch&gt;</c> — the exact fix git itself suggests for
    /// "no tracking information for the current branch". On success, also configures the
    /// upstream so subsequent plain pulls no longer need this fallback.
    /// </summary>
    private async Task<int> RetryPullWithExplicitBranchAsync(
        string repoPath,
        List<string> remotes,
        Action<string> onOutput,
        CancellationToken cancellationToken)
    {
        var currentBranch = await _gitService.GetCurrentBranchNameAsync(repoPath, cancellationToken);
        if (string.IsNullOrWhiteSpace(currentBranch))
            return -1;

        var remote = remotes.Contains("origin") ? "origin" : remotes[0];
        onOutput($"[git pull] No upstream tracking configured for '{currentBranch}' — retrying explicitly against '{remote}/{currentBranch}'...");
        AppLogger.Warn($"PullAndRestoreAsync — plain 'git pull' failed for '{repoPath}'; retrying against '{remote}/{currentBranch}'.");

        var exitCode = await RunProcessAsync(
            exePath: "git",
            arguments: ["-C", repoPath, "pull", remote, currentBranch],
            stdinInput: null,
            onOutput: onOutput,
            cancellationToken: cancellationToken);

        if (exitCode == 0)
        {
            // Best-effort: remember the tracking relationship so future plain "git pull" calls succeed.
            // A failure here doesn't affect this restore, so it isn't treated as fatal.
            var setUpstreamExit = await RunProcessAsync(
                exePath: "git",
                arguments: ["-C", repoPath, "branch", $"--set-upstream-to={remote}/{currentBranch}", currentBranch],
                stdinInput: null,
                onOutput: _ => { },
                cancellationToken: cancellationToken);

            if (setUpstreamExit != 0)
                AppLogger.Warn($"PullAndRestoreAsync — could not record upstream tracking for '{currentBranch}' in '{repoPath}' (exit {setUpstreamExit}); pull itself still succeeded.");
        }

        return exitCode;
    }

    /// <summary>
    /// Switches the working tree to <paramref name="branchName"/> before a restore, blocking
    /// (rather than silently discarding) if there are uncommitted changes.
    /// </summary>
    private async Task<bool> SwitchToBranchAsync(
        string repoPath,
        string branchName,
        Action<string> onOutput,
        CancellationToken cancellationToken)
    {
        var branches = await _gitService.GetBranchesAsync(repoPath, cancellationToken);
        var current = branches.FirstOrDefault(b => b.IsCurrent);
        if (current is not null && string.Equals(current.Name, branchName, StringComparison.Ordinal))
            return true;

        var target = branches.FirstOrDefault(b => string.Equals(b.Name, branchName, StringComparison.Ordinal));
        if (target is null)
        {
            onOutput($"[error] Branch not found: {branchName}");
            AppLogger.Warn($"PullAndRestoreAsync — requested restore branch not found: '{branchName}' in '{repoPath}'.");
            return false;
        }

        if (await _gitService.HasUncommittedChangesAsync(repoPath, cancellationToken))
        {
            onOutput("[abort] Working tree has uncommitted changes. Commit or discard them before restoring from a different branch.");
            AppLogger.Warn($"PullAndRestoreAsync blocked — uncommitted changes present in '{repoPath}'.");
            return false;
        }

        onOutput($"[checkout] Switching to branch '{branchName}' before restore...");
        var switched = await _gitService.CheckoutBranchAsync(repoPath, target.Name, target.IsRemote, onOutput, cancellationToken);
        if (!switched)
            onOutput("[abort] Could not switch to the requested branch. Restore cancelled.");

        return switched;
    }"}

