arguments.new_str:
/// <summary>
/// Pulls the latest commit from the remote and restores the ACD file using l5xgit.
/// Aborts if the git pull step fails to prevent overwriting with stale content.
/// Offers Initialize/Clone setup first when the target folder isn't a git repo yet, and
/// restores from <see cref="SelectedRestoreBranchOption"/> when a specific branch is chosen.
/// </summary>
[RelayCommand(CanExecute = nameof(CanPullAndRestore))]
private async Task PullAndRestoreAsync()
{
    if (SelectedRepo is null) return;

    if (!await EnsureGitRepositoryReadyAsync())
        return;

    IsBusy = true;
    OperationStatus = $"Restore started: {SelectedRepo.Name}";
    AppendLog($"--- Pull & Restore started: {SelectedRepo.Name} ---");
    AppLogger.Info($"PullAndRestoreAsync initiated by user for repo '{SelectedRepo.Name}'.");
    _cts = new CancellationTokenSource();

    try
    {
        var succeeded = await _cliService.PullAndRestoreAsync(
            repo: SelectedRepo.ToModel(),
            l5xGitExePath: L5xGitExePath,
            onOutput: AppendLog,
            cancellationToken: _cts.Token,
            branchName: SelectedRestoreBranchOption?.Value);

        if (succeeded)
        {
            OperationStatus = $"Restore succeeded: {SelectedRepo.Name}";
            AppendLog($"[done] Pull & restore completed successfully for {SelectedRepo.Name}.");
            AppLogger.Info($"PullAndRestoreAsync succeeded for repo '{SelectedRepo?.Name}'.");
        }
        else
        {
            OperationStatus = $"Restore failed: {SelectedRepo.Name}";
        }
    }
    catch (OperationCanceledException)
    {
        AppendLog("[cancelled] Operation was cancelled.");
        OperationStatus = $"Restore cancelled: {SelectedRepo.Name}";
        AppLogger.Info($"PullAndRestoreAsync cancelled for repo '{SelectedRepo?.Name}'.");
    }
    catch (Exception ex)
    {
        AppendLog($"[error] {ex.Message}");
        OperationStatus = $"Restore failed: {SelectedRepo.Name}";
        AppLogger.Error($"PullAndRestoreAsync failed for repo '{SelectedRepo?.Name}'.", ex);
    }
    finally
    {
        _cts?.Dispose();
        _cts = null;
        IsBusy = false;
    }

    await RefreshRestoreBranchOptionsAsync();
}

