using System.Windows;
using System.Windows.Controls;
using Microsoft.Win32;
using ABLogixGitManager.Models;
using ABLogixGitManager.Services;

namespace ABLogixGitManager.Views;

/// <summary>
/// Add/Edit dialog for a controller mapping. Supports three repository sources: an existing
/// local folder (previous default behavior), cloning a remote repository, or initializing a new
/// local repository — the latter two are performed synchronously (relative to this dialog) before
/// the mapping is saved, so a freshly added mapping is immediately usable by Commit/Pull &amp; Restore.
/// </summary>
public partial class AddEditRepoWindow : Window
{
    private enum SourceMode
    {
        ExistingFolder = 0,
        Clone = 1,
        CreateNew = 2,
    }

    private readonly L5xGitCliService _cliService = new();

    /// <summary>Set when the user clicks Save; null if cancelled.</summary>
    public RepoEntry? Result { get; private set; }

    private readonly Guid _existingId;

    public AddEditRepoWindow(RepoEntry? existing = null)
    {
        InitializeComponent();

        _existingId = existing?.Id ?? Guid.NewGuid();

        if (existing is not null)
        {
            NameBox.Text = existing.Name;
            AcdPathBox.Text = existing.AcdFilePath;
            GitRepoPathBox.Text = existing.GitRepoPath;
        }

        // Default to "existing folder" — the only mode that made sense before this dialog could
        // clone/init directly, and the correct choice when editing a mapping that already works.
        SourceModeBox.SelectedIndex = (int)SourceMode.ExistingFolder;

        NameBox.Focus();
    }

    private SourceMode SelectedMode => (SourceMode)SourceModeBox.SelectedIndex;

    private void SourceModeBox_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        var isClone = SelectedMode == SourceMode.Clone;
        RemoteUrlLabel.Visibility = isClone ? Visibility.Visible : Visibility.Collapsed;
        RemoteUrlBox.Visibility = isClone ? Visibility.Visible : Visibility.Collapsed;

        GitRepoPathLabel.Text = SelectedMode switch
        {
            SourceMode.Clone => "CLONE DESTINATION FOLDER (must be empty or not yet exist)",
            SourceMode.CreateNew => "NEW REPOSITORY FOLDER",
            _ => "GIT REPO / EXPLODED DIRECTORY PATH",
        };

        HideStatus();
    }

    private void BrowseAcd_Click(object sender, RoutedEventArgs e)
    {
        var dialog = new OpenFileDialog
        {
            Title = "Select ACD File",
            Filter = "ACD Files (*.ACD)|*.ACD;*.acd|All Files (*.*)|*.*",
            CheckFileExists = false,
        };

        if (!string.IsNullOrWhiteSpace(AcdPathBox.Text))
        {
            var dir = Path.GetDirectoryName(AcdPathBox.Text);
            if (Directory.Exists(dir)) dialog.InitialDirectory = dir;
        }

        if (dialog.ShowDialog(this) == true)
            AcdPathBox.Text = dialog.FileName;
    }

    private void BrowseGitRepo_Click(object sender, RoutedEventArgs e)
    {
        // Use OpenFolderDialog (available in WPF on .NET 8+)
        var dialog = new OpenFolderDialog
        {
            Title = "Select Git Repo / Exploded Directory",
        };

        if (!string.IsNullOrWhiteSpace(GitRepoPathBox.Text) &&
            Directory.Exists(GitRepoPathBox.Text))
        {
            dialog.InitialDirectory = GitRepoPathBox.Text;
        }

        if (dialog.ShowDialog(this) == true)
            GitRepoPathBox.Text = dialog.FolderName;
    }

    private async void Ok_Click(object sender, RoutedEventArgs e)
    {
        if (string.IsNullOrWhiteSpace(NameBox.Text))
        {
            MessageBox.Show("Please enter a friendly name.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
            NameBox.Focus();
            return;
        }

        if (string.IsNullOrWhiteSpace(AcdPathBox.Text))
        {
            MessageBox.Show("Please specify the ACD file path.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
            AcdPathBox.Focus();
            return;
        }

        if (string.IsNullOrWhiteSpace(GitRepoPathBox.Text))
        {
            MessageBox.Show("Please specify the Git repo / exploded directory path.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
            GitRepoPathBox.Focus();
            return;
        }

        if (SelectedMode == SourceMode.Clone && string.IsNullOrWhiteSpace(RemoteUrlBox.Text))
        {
            MessageBox.Show("Please enter a remote URL to clone.", "Validation", MessageBoxButton.OK, MessageBoxImage.Warning);
            RemoteUrlBox.Focus();
            return;
        }

        if (SelectedMode is SourceMode.Clone or SourceMode.CreateNew &&
            !await SetUpRepositoryAsync())
        {
            return; // Error already shown via the status text.
        }

        Result = new RepoEntry
        {
            Id = _existingId,
            Name = NameBox.Text.Trim(),
            AcdFilePath = AcdPathBox.Text.Trim(),
            GitRepoPath = GitRepoPathBox.Text.Trim(),
        };

        DialogResult = true;
    }

    /// <summary>
    /// Runs <c>git clone</c> or <c>git init</c> against the configured Git Repo Path before the
    /// mapping is saved, so a brand-new mapping is immediately ready for Commit/Pull &amp; Restore
    /// instead of failing later with "not a git repository".
    /// </summary>
    private async Task<bool> SetUpRepositoryAsync()
    {
        var repoPath = GitRepoPathBox.Text.Trim();
        var log = new List<string>();

        SetFormEnabled(false);
        ShowStatus(SelectedMode == SourceMode.Clone ? "Cloning repository…" : "Initializing repository…", isError: false);
        AppLogger.Info($"AddEditRepoWindow — starting repository setup (mode: {SelectedMode}) for '{repoPath}'.");

        try
        {
            bool ok;
            if (SelectedMode == SourceMode.Clone)
            {
                ok = await _cliService.CloneRepositoryAsync(RemoteUrlBox.Text.Trim(), repoPath, log.Add);
            }
            else
            {
                Directory.CreateDirectory(repoPath);
                ok = await _cliService.InitializeGitRepositoryAsync(repoPath, log.Add);
            }

            if (!ok)
            {
                var tail = string.Join(Environment.NewLine, log.TakeLast(5));
                ShowStatus(string.IsNullOrWhiteSpace(tail) ? "Repository setup failed. Check the path and try again." : tail, isError: true);
                AppLogger.Warn($"AddEditRepoWindow — repository setup failed (mode: {SelectedMode}) for '{repoPath}'.");
                return false;
            }

            AppLogger.Info($"AddEditRepoWindow — repository setup succeeded (mode: {SelectedMode}) for '{repoPath}'.");
            return true;
        }
        catch (Exception ex)
        {
            ShowStatus($"Repository setup failed: {ex.Message}", isError: true);
            AppLogger.Error($"AddEditRepoWindow — repository setup threw (mode: {SelectedMode}) for '{repoPath}'.", ex);
            return false;
        }
        finally
        {
            SetFormEnabled(true);
        }
    }

    private void SetFormEnabled(bool enabled)
    {
        NameBox.IsEnabled = enabled;
        SourceModeBox.IsEnabled = enabled;
        RemoteUrlBox.IsEnabled = enabled;
        AcdPathBox.IsEnabled = enabled;
        GitRepoPathBox.IsEnabled = enabled;
        OkButton.IsEnabled = enabled;
    }

    private void ShowStatus(string text, bool isError)
    {
        StatusText.Text = text;
        StatusText.Foreground = (System.Windows.Media.Brush)FindResource(isError ? "DangerBrush" : "FaintBrush");
        StatusText.Visibility = Visibility.Visible;
    }

    private void HideStatus() => StatusText.Visibility = Visibility.Collapsed;

    private void Cancel_Click(object sender, RoutedEventArgs e)
    {
        DialogResult = false;
    }
}"}

